source = '''from collections import Counter, deque

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    component_at = {}
    component_color = {}
    target_colors = set()
    seen = set()
    next_component = 0
    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < rows and 0 <= nx < cols and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            for y, x in cells:
                component_at[y, x] = next_component
            component_color[next_component] = color
            if len(cells) > 1:
                target_colors.add(color)
            next_component += 1
    out = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color == background or color in target_colors:
                continue
            adjacent = Counter(component_at[ny, nx]
                               for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1))
                               if 0 <= (ny := r + dy) < rows and 0 <= (nx := c + dx) < cols
                               and (ny, nx) in component_at
                               and len_component(component_at[ny, nx], grid, component_at) > 1)
            candidates = [cid for cid, count in adjacent.items() if count >= 2]
            if len(candidates) == 1:
                out[r][c] = component_color[candidates[0]]
            else:
                out[r][c] = background
    return out

def len_component(cid, grid, component_at):
    return sum(1 for key, value in component_at.items() if value == cid)
'''
